interface MarkProps {
  className?: string;
  title?: string;
}

/** The T-and-J glyph alone (34:17). */
export function LogoMark({ className, title }: MarkProps) {
  return (
    <svg
      viewBox="0 0 34 17"
      fill="currentColor"
      className={cn("h-4 w-auto", className)}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
    >
      {title && <title>{title}</title>}
      {MARK_PATHS.map((d) => (
        <path key={d} d={d} />
      ))}
    </svg>
  );
}

/** The "Truebex" wordmark alone (91:19). */
export function Wordmark({ className, title }: MarkProps) {
  return (
    <svg
      viewBox="0 0 91 19"
      fill="currentColor"
      className={cn("h-4 w-auto", className)}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
    >
      {title && <title>{title}</title>}
      <path d={WORDMARK_PATH} />
    </svg>
  );
}

/** Glyph + wordmark, the primary lockup. Height drives the size. Always
 *  left to right: the lockup never mirrors, on the Arabic page included. */
export function Lockup({ className }: { className?: string }) {
  return (
    <span
      className={cn("inline-flex items-center gap-[0.45em] text-brand-fg", className)}
      role="img"
      aria-label="Truebex"
      dir="ltr"
    >
      <LogoMark className="h-[0.9em]" />
      <Wordmark className="h-[1em]" />
    </span>
  );
}
